const css = `
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;1,600&display=swap');

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: #fffdfb;
  color: #2b1c23;
  font-family: "DM Sans", sans-serif;
}

button,
input {
  font-family: inherit;
}

button {
  cursor: pointer;
}

a {
  text-decoration: none;
  color: inherit;
}

.shop {
  min-height: 100vh;
  overflow: hidden;
}

.topbar {
  min-height: 34px;
  background: #281b22;
  color: white;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  padding: 8px 20px;
  font-size: 11px;
}

.header {
  height: 82px;
  max-width: 1400px;
  margin: auto;
  padding: 0 5%;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo,
.footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #77364c;
  color: white;
  display: grid;
  place-items: center;
  font-size: 22px;
  font-family: "Playfair Display", serif;
  font-style: italic;
}

.logo > div:last-child,
.footer-logo > div:last-child {
  display: flex;
  flex-direction: column;
}

.logo strong,
.footer-logo strong {
  font-size: 14px;
  letter-spacing: 3px;
}

.logo small,
.footer-logo small {
  font-size: 8px;
  color: #85777e;
  letter-spacing: 1.5px;
  margin-top: 4px;
}

nav {
  display: flex;
  gap: 30px;
}

nav a {
  font-size: 12px;
  font-weight: 600;
}

.cart-button {
  background: #281b22;
  color: white;
  border: none;
  height: 42px;
  border-radius: 30px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 9px 0 15px;
}

.cart-button span {
  font-size: 11px;
  font-weight: 700;
}

.cart-button b {
  background: white;
  color: #281b22;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 10px;
}

.hero {
  min-height: 650px;
  background: linear-gradient(
    120deg,
    #f9f4ef,
    #fffdfb 50%,
    #f0dfd8
  );
  padding: 70px max(5%, calc((100vw - 1300px) / 2));
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 60px;
  align-items: center;
}

.small-title {
  color: #8d4058;
  letter-spacing: 2px;
  font-size: 10px;
  font-weight: 700;
}

.hero h1 {
  font-family: "Playfair Display", serif;
  font-size: clamp(50px, 5vw, 76px);
  line-height: 1;
  margin: 18px 0 22px;
}

.hero h1 em,
.about h2 em {
  color: #a44561;
}

.hero-content > p {
  max-width: 520px;
  color: #766a70;
  font-size: 15px;
  line-height: 1.8;
}

.hero-buttons {
  display: flex;
  align-items: center;
  gap: 25px;
  margin-top: 32px;
}

.primary,
.whatsapp {
  min-height: 52px;
  padding: 0 23px;
  background: #77364c;
  color: white;
  border-radius: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}

.secondary {
  font-size: 11px;
  font-weight: 700;
  border-bottom: 1px solid #281b22;
}

.hero-details {
  margin-top: 45px;
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
}

.hero-details span {
  font-size: 10px;
  color: #766a70;
}

.hero-images {
  height: 530px;
  position: relative;
}

.hero-circle {
  width: 400px;
  height: 400px;
  background: #ead1c7;
  border-radius: 50%;
  position: absolute;
  right: 50px;
  top: 40px;
}

.hero-main {
  position: absolute;
  width: 55%;
  height: 90%;
  right: 8%;
  top: 0;
  object-fit: cover;
  border-radius: 200px 200px 15px 15px;
  box-shadow: 0 30px 60px rgba(50,20,30,.15);
}

.hero-small {
  position: absolute;
  width: 30%;
  height: 42%;
  object-fit: cover;
  bottom: 0;
  left: 8%;
  border-radius: 100px 100px 10px 10px;
  border: 8px solid #fffdfb;
}

.hero-product {
  position: absolute;
  bottom: 35px;
  right: 0;
  background: rgba(255,255,255,.95);
  padding: 18px;
  width: 180px;
  border-radius: 13px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 20px 40px rgba(50,20,30,.12);
}

.hero-product small {
  color: #a44561;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1px;
}

.hero-product strong {
  font-family: "Playfair Display", serif;
  font-size: 20px;
  margin: 8px 0 5px;
}

.hero-product span {
  font-size: 10px;
  color: #766a70;
}

.services {
  max-width: 1200px;
  margin: -28px auto 0;
  position: relative;
  background: white;
  border-radius: 14px;
  box-shadow: 0 20px 50px rgba(40,20,30,.1);
  display: grid;
  grid-template-columns: repeat(3,1fr);
  padding: 22px;
}

.services > div {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 8px 25px;
  border-right: 1px solid #eee2dc;
}

.services > div:last-child {
  border: none;
}

.service-icon {
  font-size: 24px;
}

.services section {
  display: flex;
  flex-direction: column;
}

.services strong {
  font-size: 11px;
}

.services small {
  font-size: 9px;
  color: #82777c;
  margin-top: 4px;
}

.collection {
  max-width: 1300px;
  margin: auto;
  padding: 110px 30px;
}

.collection-title {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 30px;
}

.collection h2,
.about h2,
.newsletter h2 {
  font-family: "Playfair Display", serif;
  font-size: 50px;
  margin: 8px 0 0;
}

.search {
  height: 46px;
  width: 260px;
  border: 1px solid #e8ded9;
  border-radius: 30px;
  display: flex;
  align-items: center;
  padding: 0 15px;
  gap: 10px;
}

.search input {
  border: none;
  outline: none;
  width: 100%;
  background: transparent;
  font-size: 11px;
}

.categories {
  display: flex;
  gap: 8px;
  margin: 32px 0;
  overflow-x: auto;
}

.categories button {
  flex: 0 0 auto;
  border: 1px solid #e6dcd7;
  background: white;
  padding: 10px 16px;
  border-radius: 30px;
  font-size: 10px;
  font-weight: 600;
}

.categories .active {
  background: #281b22;
  color: white;
  border-color: #281b22;
}

.products {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 35px 20px;
}

.product-image {
  height: 450px;
  position: relative;
  overflow: hidden;
  border-radius: 12px;
  background: #eee3dd;
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: .4s;
}

.product:hover img {
  transform: scale(1.035);
}

.category {
  position: absolute;
  top: 12px;
  left: 12px;
  background: white;
  padding: 7px 11px;
  border-radius: 20px;
  font-size: 8px;
  font-weight: 700;
}

.heart {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 37px;
  height: 37px;
  border-radius: 50%;
  border: none;
  background: white;
  font-size: 20px;
}

.heart.liked {
  color: #a44561;
}

.add {
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 14px;
  height: 43px;
  background: rgba(40,27,34,.94);
  color: white;
  border: none;
  border-radius: 30px;
  font-size: 10px;
  font-weight: 700;
  opacity: 0;
  transform: translateY(10px);
  transition: .25s;
}

.product:hover .add {
  opacity: 1;
  transform: translateY(0);
}

.product-info {
  padding: 14px 4px;
}

.product-info small {
  color: #8b7d83;
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.product-info h3 {
  font-family: "Playfair Display", serif;
  font-size: 20px;
  margin: 4px 0 8px;
}

.price {
  display: flex;
  gap: 10px;
  align-items: center;
}

.price strong {
  color: #77364c;
  font-size: 13px;
}

.price del {
