  font-weight: 700;
}

.remove {
  margin-top: auto;
  align-self: flex-start;
  border: none;
  background: transparent;
  color: #9c5367;
  padding: 0;
  font-size: 9px;
  text-decoration: underline;
}

.cart-footer {
