import React, { useMemo, useState } from "react";

const products = [
  {
    id: 1,
    name: "Robe Soa",
    category: "Nouveautés",
    price: 129000,
    oldPrice: 149000,
    image:
      "https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=800&q=85",
  },
  {
    id: 2,
    name: "Robe Mialy",
    category: "Soirée",
    price: 159000,
    image:
      "https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=800&q=85",
  },
  {
    id: 3,
    name: "Robe Vola",
    category: "Décontractée",
    price: 99000,
    image:
      "https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=800&q=85",
  },
  {
    id: 4,
    name: "Robe Fara",
    category: "Cérémonie",
    price: 139000,
    image:
      "https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&w=800&q=85",
  },
  {
    id: 5,
    name: "Robe Kanto",
    category: "Décontractée",
    price: 119000,
    image:
      "https://images.unsplash.com/photo-1539109136881-3be0616acf4b?auto=format&fit=crop&w=800&q=85",
  },
  {
    id: 6,
    name: "Robe Tahina",
    category: "Soirée",
    price: 179000,
    image:
      "https://images.unsplash.com/photo-1502716119720-b23a1e3ae1b5?auto=format&fit=crop&w=800&q=85",
  },
];

const categories = [
  "Toutes",
  "Nouveautés",
  "Soirée",
  "Cérémonie",
  "Décontractée",
];

function formatPrice(price) {
  return new Intl.NumberFormat("fr-FR").format(price) + " Ar";
}

export default function App() {
  const [category, setCategory] = useState("Toutes");
  const [search, setSearch] = useState("");
  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);
  const [favorites, setFavorites] = useState([]);

  const filteredProducts = useMemo(() => {
    return products.filter((product) => {
      const categoryMatch =
        category === "Toutes" || product.category === category;

      const searchMatch = product.name
        .toLowerCase()
        .includes(search.toLowerCase());

      return categoryMatch && searchMatch;
    });
  }, [category, search]);

  const addToCart = (product) => {
    setCart((current) => {
      const exists = current.find((item) => item.id === product.id);

      if (exists) {
        return current.map((item) =>
          item.id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }

      return [...current, { ...product, quantity: 1 }];
    });

    setCartOpen(true);
  };

  const removeFromCart = (id) => {
    setCart((current) => current.filter((item) => item.id !== id));
  };

  const changeQuantity = (id, amount) => {
    setCart((current) =>
      current
        .map((item) =>
          item.id === id
            ? {
                ...item,
                quantity: item.quantity + amount,
              }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const toggleFavorite = (id) => {
    setFavorites((current) =>
      current.includes(id)
        ? current.filter((item) => item !== id)
        : [...current, id]
    );
  };

  const cartTotal = cart.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );

  const cartCount = cart.reduce(
    (total, item) => total + item.quantity,
    0
  );

  const orderWhatsApp = () => {
    const productsText = cart
      .map(
        (item) =>
          `${item.name} x${item.quantity} - ${formatPrice(
            item.price * item.quantity
          )}`
      )
      .join("\n");

    const message = `
Bonjour Ravaka 👋

Je souhaite commander :

${productsText}

Total : ${formatPrice(cartTotal)}
    `;

    // Remplace ce numéro par ton vrai numéro WhatsApp Madagascar.
    const whatsappNumber = "261340000000";

    window.open(
      `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`,
      "_blank"
    );
  };

  return (
    <>
      <style>{css}</style>

      <div className="shop">
        {/* BARRE DU HAUT */}
        <div className="topbar">
          Livraison disponible partout à Madagascar 🇲🇬
          <span>•</span>
          Paiement MVola, Orange Money & Airtel Money
        </div>

        {/* HEADER */}
        <header className="header">
          <a href="#" className="logo">
            <div className="logo-icon">R</div>

            <div>
              <strong>RAVAKA</strong>
              <small>FEMME • MADAGASCAR</small>
            </div>
          </a>

          <nav>
            <a href="#collection">Nouveautés</a>
            <a href="#collection">Robes</a>
            <a href="#about">À propos</a>
            <a href="#delivery">Livraison</a>
          </nav>

          <button
            className="cart-button"
            onClick={() => setCartOpen(true)}
          >
            🛍️
            <span>Panier</span>
            <b>{cartCount}</b>
          </button>
        </header>

        {/* HERO */}
        <section className="hero">
          <div className="hero-content">
            <span className="small-title">
              ✦ COLLECTION FEMME
            </span>

            <h1>
              La robe parfaite
              <br />
              pour <em>vous révéler.</em>
            </h1>

            <p>
              Découvrez une sélection de robes élégantes,
              modernes et féminines, disponibles à Madagascar.
            </p>

            <div className="hero-buttons">
              <a href="#collection" className="primary">
                Découvrir la collection →
              </a>

              <a href="#about" className="secondary">
                Notre univers
              </a>
            </div>

            <div className="hero-details">
              <span>✓ Prix en Ariary</span>
              <span>✓ Livraison Madagascar</span>
              <span>✓ Commande WhatsApp</span>
            </div>
          </div>

          <div className="hero-images">
            <div className="hero-circle"></div>

            <img
              className="hero-main"
              src="https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=1000&q=90"
              alt="Robe femme"
            />

            <img
              className="hero-small"
              src="https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=600&q=90"
              alt="Mode femme"
            />

            <div className="hero-product">
              <small>NOUVELLE PIÈCE</small>
              <strong>Robe Mialy</strong>
              <span>159 000 Ar</span>
            </div>
          </div>
        </section>

        {/* SERVICES */}
        <section className="services" id="delivery">
          <div>
            <span className="service-icon">🚚</span>

            <section>
              <strong>Livraison Madagascar</strong>
              <small>Antananarivo & provinces</small>
            </section>
          </div>

          <div>
            <span className="service-icon">📱</span>

            <section>
              <strong>Paiement mobile</strong>
              <small>MVola, Orange Money, Airtel Money</small>
            </section>
          </div>

          <div>
            <span className="service-icon">💬</span>

            <section>
              <strong>Commande WhatsApp</strong>
              <small>Simple, rapide et pratique</small>
            </section>
          </div>
        </section>

        {/* PRODUITS */}
        <section className="collection" id="collection">
          <div className="collection-title">
            <div>
              <span className="small-title">SÉLECTION RAVAKA</span>
              <h2>Nos robes du moment</h2>
            </div>

            <div className="search">
              🔎

              <input
                type="text"
                placeholder="Rechercher une robe..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>

          {/* CATEGORIES */}
          <div className="categories">
            {categories.map((item) => (
              <button
                key={item}
                className={category === item ? "active" : ""}
                onClick={() => setCategory(item)}
              >
                {item}
              </button>
            ))}
          </div>

          {/* GRID */}
          <div className="products">
            {filteredProducts.map((product) => {
              const liked = favorites.includes(product.id);

              return (
                <article className="product" key={product.id}>
                  <div className="product-image">
                    <img src={product.image} alt={product.name} />

                    <span className="category">
                      {product.category}
                    </span>

                    <button
                      className={`heart ${liked ? "liked" : ""}`}
                      onClick={() => toggleFavorite(product.id)}
                    >
                      {liked ? "♥" : "♡"}
                    </button>

                    <button
                      className="add"
                      onClick={() => addToCart(product)}
                    >
                      Ajouter au panier
                    </button>
                  </div>

                  <div className="product-info">
                    <div>
                      <small>{product.category}</small>
                      <h3>{product.name}</h3>
                    </div>

                    <div className="price">
                      <strong>{formatPrice(product.price)}</strong>

                      {product.oldPrice && (
                        <del>{formatPrice(product.oldPrice)}</del>
                      )}
                    </div>

                    <div className="sizes">
                      <span>S</span>
                      <span>M</span>
                      <span>L</span>
                      <span>XL</span>
                    </div>
                  </div>
                </article>
              );
            })}
          </div>

          {filteredProducts.length === 0 && (
            <div className="empty">
              <h3>Aucune robe trouvée</h3>
              <p>Essayez une autre recherche.</p>
            </div>
          )}
        </section>

        {/* ABOUT */}
        <section className="about" id="about">
          <div className="about-image">
            <img
              src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1000&q=85"
              alt="Boutique mode"
            />
          </div>

          <div className="about-text">
            <span className="small-title">
              NOTRE UNIVERS
            </span>

            <h2>
              Élégante.
              <br />
              Moderne.
              <br />
              <em>Malagasy.</em>
            </h2>

            <p>
              Ravaka est une boutique dédiée aux femmes qui
              souhaitent trouver facilement des robes élégantes
              et tendances à Madagascar.
            </p>

            <ul>
              <li>✓ Commande simple</li>
              <li>✓ Assistance WhatsApp</li>
              <li>✓ Paiement en Ariary</li>
              <li>✓ Livraison nationale</li>
            </ul>

            <a
              href="https://wa.me/261340000000"
              target="_blank"
              rel="noreferrer"
              className="whatsapp"
            >
              💬 Nous contacter sur WhatsApp
            </a>
          </div>
        </section>

        {/* NEWSLETTER */}
        <section className="newsletter">
          <div>
            <span className="small-title">
              RESTEZ INFORMÉE
            </span>

            <h2>
              Recevez nos nouvelles collections.
            </h2>
          </div>

          <form
            onSubmit={(e) => {
              e.preventDefault();
              alert("Merci pour votre inscription !");
            }}
          >
            <input
              type="email"
              placeholder="Votre adresse e-mail"
              required
            />

            <button>S'inscrire →</button>
          </form>
        </section>

        {/* FOOTER */}
        <footer>
          <div className="footer-logo">
            <div className="logo-icon">R</div>

            <div>
              <strong>RAVAKA</strong>
              <small>FEMME • MADAGASCAR</small>
            </div>
          </div>

          <p>
            Boutique de robes pour femme à Madagascar.
          </p>

          <div className="footer-links">
            <a href="#">Instagram</a>
            <a href="#">Facebook</a>
            <a href="#">TikTok</a>
          </div>

          <small>
            © 2026 Ravaka Madagascar. Tous droits réservés.
          </small>
        </footer>

        {/* PANIER */}
        {cartOpen && (
          <div
            className="cart-overlay"
            onClick={() => setCartOpen(false)}
          >
            <div
              className="cart"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="cart-header">
                <div>
                  <h2>Votre panier</h2>
                  <small>{cartCount} article(s)</small>
                </div>

                <button onClick={() => setCartOpen(false)}>
                  ✕
                </button>
              </div>

              <div className="cart-content">
                {cart.length === 0 ? (
                  <div className="cart-empty">
                    <span>🛍️</span>
                    <h3>Votre panier est vide</h3>
                    <p>
                      Ajoutez quelques robes à votre panier.
                    </p>
                  </div>
                ) : (
                  cart.map((item) => (
                    <div className="cart-item" key={item.id}>
                      <img src={item.image} alt={item.name} />

                      <div className="cart-item-info">
                        <h4>{item.name}</h4>

                        <strong>
                          {formatPrice(item.price)}
                        </strong>

                        <div className="quantity">
                          <button
                            onClick={() =>
                              changeQuantity(item.id, -1)
                            }
                          >
                            −
                          </button>

                          <span>{item.quantity}</span>

                          <button
                            onClick={() =>
                              changeQuantity(item.id, 1)
                            }
                          >
                            +
                          </button>
                        </div>

                        <button
                          className="remove"
                          onClick={() =>
                            removeFromCart(item.id)
                          }
                        >
                          Supprimer
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>

              {cart.length > 0 && (
                <div className="cart-footer">
                  <div className="total">
                    <span>Total</span>
                    <strong>
                      {formatPrice(cartTotal)}
                    </strong>
                  </div>

                  <small>
                    Livraison calculée lors de la confirmation.
                  </small>

                  <button
                    className="checkout"
                    onClick={orderWhatsApp}
                  >
                    Commander sur WhatsApp →
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </>
  );
}

const css = `
